package it.gestionechiavi.mezzi
import android.Manifest;import android.content.Intent;import android.content.pm.PackageManager;import android.os.Bundle;import androidx.activity.result.contract.ActivityResultContracts;import androidx.appcompat.app.AppCompatActivity;import androidx.camera.core.*;import androidx.camera.lifecycle.ProcessCameraProvider;import androidx.core.content.ContextCompat;import com.google.mlkit.vision.barcode.BarcodeScanning;import com.google.mlkit.vision.barcode.common.Barcode;import com.google.mlkit.vision.common.InputImage;import java.util.concurrent.Executors
class ScannerActivity:AppCompatActivity(){private val exec=Executors.newSingleThreadExecutor();private var done=false;private val permission=registerForActivityResult(ActivityResultContracts.RequestPermission()){if(it)start()else finish()};override fun onCreate(b:Bundle?){super.onCreate(b);setContentView(R.layout.activity_scanner);if(ContextCompat.checkSelfPermission(this,Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED)start()else permission.launch(Manifest.permission.CAMERA)};private fun start(){val f=ProcessCameraProvider.getInstance(this);f.addListener({val p=f.get();val preview=Preview.Builder().build().also{it.setSurfaceProvider(findViewById<androidx.camera.view.PreviewView>(R.id.preview).surfaceProvider)};val analysis=ImageAnalysis.Builder().setBackpressureStrategy(ImageAnalysis.STRATEGY_KEEP_ONLY_LATEST).build();val scanner=BarcodeScanning.getClient();analysis.setAnalyzer(exec){proxy->val img=proxy.image;if(img==null){proxy.close();return@setAnalyzer};scanner.process(InputImage.fromMediaImage(img,proxy.imageInfo.rotationDegrees)).addOnSuccessListener{codes->codes.firstOrNull{it.format==Barcode.FORMAT_QR_CODE}?.rawValue?.let{v->if(!done){done=true;setResult(RESULT_OK,Intent().putExtra("qr",v));finish()}}}.addOnCompleteListener{proxy.close()}};p.unbindAll();p.bindToLifecycle(this,CameraSelector.DEFAULT_BACK_CAMERA,preview,analysis)},ContextCompat.getMainExecutor(this))};override fun onDestroy(){exec.shutdown();super.onDestroy()}}
